import { action } from "solid-js";
const real = globalThis.atob;
// The global object, handed back by a message's `source`: the browser sets it to the window that posted the message.
addEventListener("message", (message) => {
  if (message.data !== "fz-wsource") return;
  message.source.atob = (text) => {
    void action(function* () {})();
    return real(text);
  };
});
postMessage("fz-wsource", "*");
